"""Generate inspectable cap/tail numerical tables and conclusions."""
import json
import numpy as np,pandas as pd
from .full_readout_fit import HERE,dump
from .cap_tail_study import VARIANTS


def run():
    root=HERE/'runs/m2_cap_tail_001';prior=HERE/'runs/m2_maturity_curve_fit_001';assert (root/'followup/run.json').exists();lines=[]
    def add(s=''):lines.append(s)
    add('# Cap and tail investigation: bounded experiments');add();add('Completed 25 October 2026. The selected baseline remains `runs/m2_maturity_curve_fit_001/selected_model.json`. No new joint calibration is adopted. New evidence is isolated in `runs/m2_cap_tail_001/`. Original runs, selected configuration and production kernels are unchanged.');add()
    add('The cap compresses payoff-relevant extreme-state responses and changing it steepens the wing. Its finite support is not the binding obstruction at the quoted strikes. Neither raising the transition nor the tested continuous alternatives solves the smile. New VIX-focused curve fits expose additional flexibility with severe SPX tradeoffs and weakly identified variance pieces.');add()
    add('## Scope and correspondence');add();add('All seven SPX dates29/57/119/211/302/666/1030 and all four VIX dates27/55/118/153,1511 original OTM quotes and four forwards, cutoff3, common-call payoff and all4096 samples at every strike. Market puts use market-forward parity; native model puts use model forwards. OU rates/geometric grids, initial state, correlations and risk-price scenario are fixed. GH32/GH48/time8 and stock512 remain baseline approximations. Experimental kernels and additional quadrature tables are separate. No jumps or quintic approach was explored.');add()
    replay=json.loads((root/'baseline_replay.json').read_text());add(f"The new baseline VIX repricing differs from saved selected prices by at most{replay['maximum_price_difference']:.3g} VIX option-price points. Independent saved-draw replay verifies the parent selection before using it. Equations, integrability and martingality arguments: [CAP_TAIL_MATHEMATICS.md](CAP_TAIL_MATHEMATICS.md). Designs/literature/cache costs: [STOCHASTIC_VOL_OF_VOL_RESEARCH.md](STOCHASTIC_VOL_OF_VOL_RESEARCH.md).");add()
    add('## Range and weighted tails');add();add('Numerically evaluated cap upper bounds are936.52/949.28/976.28/1003.19, versus highest quoted strikes100/170/200/200. Those bounds alone do not establish attainability. Saved separate-checking VIX maxima425.17/431.81/543.95/508.56 independently show implemented conditional values exceeding the quoted strikes.');add()
    t=pd.read_csv(root/'parent_checking_tails.csv');add('|Days|Highest strike|Proposal hits /4096|Weighted Q probability|Raw call ± scramble SE|Payoff ESS|Top10 payoff share|');add('|---:|---:|---:|---:|---:|---:|---:|')
    for day,g in t.groupby('days'):
        r=g.loc[g.strike.idxmax()];add(f"|{day}|{r.strike:g}|{int(r.hits)}|{r.probability:.6g}|{r.raw_call:.6g} ± {r.call_SE:.2g}|{r.payoff_ESS:.1f}|{100*r.top10_share:.1f}%|")
    add();add('Hits are proposal frequencies, not risk-neutral frequencies. Probability uses mean[w*indicator]; raw call uses mean[w*(VIX-K)+], without self normalization. Payoff ESS and concentration are descriptive. Actual controlled prices retain signed zero-mean corrections. Eight independent scramble means provide sampling SE, excluding deterministic bias, frozen pilot and parameter uncertainty.');add()
    add('At the four window midpoints, only roughly0.0066–0.0086% of direct-Q probability lies above eta=L, but those states contribute8.8–10.4% of E[G]. G-weighted mean response h\'(eta) is0.86–0.88 overall. Highest-strike-call-weighted conditional responses at the window midpoint are0.662/0.597/0.574/0.577. Thus saturation is relevant to wing contributors even though their VIX values need not approach the global upper bound. Marginal diagnostics use eight NEW scrambled32768-point Gaussian-mixture importance nets per date, with saved seeds and exact p/q weights.');add()
    add('## Fixed-curve cap profiles');add();add('Only the tempering function changes here; each candidate rebuilds its own Q normalizer. Curve/floor and original score coefficients stay fixed. These are finite profiles, not optimized families.');add();add('|Candidate|Native VIX options|Forwards|Native VIX + forwards|Unavailable call IVs|VIX evaluation seconds|');add('|---|---:|---:|---:|---:|---:|')
    records=json.loads((root/'scores.json').read_text())
    for r in records:
        c=r['original_otm_components'];add(f"|{r['candidate']}|{c['VIX']:.6f}|{c['forwards']:.6f}|{c['VIX']+c['forwards']:.6f}|{r['iv_unavailable']}|{r['seconds']:.2f}|")
    add();add('The logarithmic continuation is h_original+a*log(1+softplus(k*(eta-L))/k), so G grows only polynomially in the Gaussian score beyond the transition. All its Gaussian multiplier moments exist. Algebraic saturation matches the original transition value/slope and changes its approach to the plateau. Separate-channel caps keep the linear C channel outside individual Y/F caps; the tested3/2.5 allocation is poor. Their equations are recorded in the mathematics report.');add()
    add('Raising L strengthens tails AND increases M_Q. It therefore reduces normalized variance in many ordinary states. At fixed xi this changes VIX forward and near-ATM fit as well as wings. The L+.75 profile has VIX forwards19.870/20.632/21.267/21.822 versus baseline20.227/21.094/21.782/22.346 and market20.10/20.73/21.19/21.72. The resulting forward improvement does not prevent option-price loss from worsening.');add()
    add('|Days|Market right-wing IV slope|Baseline|L+.75|Log a=.25|Log a=.50|');add('|---:|---:|---:|---:|---:|---:|')
    from .plot_maturity_curve import iv
    shape=pd.read_csv(HERE/'visualizations/cap-tail-014/smile-shape.csv')
    b=pd.read_csv(root/'prices_canonical_baseline.csv')
    for day,g in b.groupby('expiry_days'):
        mask=g.K_over_F>2;market=float(np.polyfit(np.log(g.K_over_F[mask]),iv(g,g.price_mid_U)[mask],1)[0]);vals=[float(shape[(shape.candidate==n)&shape.days.eq(day)&shape.region.eq('right')].slope_per_logstrike.iloc[0]) for n in ['baseline','higher_L','logtail025','logtail050']];add(f'|{day}|{market:.2f}|'+ '|'.join(f'{v:.2f}' for v in vals)+'|')
    add();add('Slope is a descriptive least-squares slope of raw IV against log(K/F), restricted to K/F>2, in percentage points per unit log strike. It is not an asymptotic slope, smoothed price curve or new calibration objective. Curvature, ATM level/MAE and available-IV counts are saved in `visualizations/cap-tail-014/smile-shape.csv`. All variants leave material shape deficits.');add()
    add('At153 days and K=200, actual training call price is0.001275 at baseline,0.006352 at L+.75 and0.002362 for log a=.25; market midpoint is0.141629. Their pointwise sampling SEs are0.000094/0.000614/0.000161. Tail strengthening is substantial in relative terms but much smaller than the price gap. Small SE is not a guarantee against unsampled tails or deterministic bias.');add()
    add('## VIX-focused fits and actual SPX tradeoffs');add();add('Training profiles selected L+.75 and log a=.25 for follow-up before separate checking. Two bounded least-squares fits free16 curve levels and floor, holding their readout/cap fixed, with no joint safeguards. The fit parametrization enforces xi>=f and xi<=.2; floor volatility remains5–6% for comparability. The6% endpoint and .2 curve upper bound are implementation choices. Both optimizers report local ftol termination; neither is a global convergence result.');add()
    add('|Candidate|Training native VIX + forward|Training common-call VIX + forward|Separate reused native VIX checking|Training SPX|Training native joint|');add('|---|---:|---:|---:|---:|---:|')
    base=json.loads((prior/'score_selected.json').read_text());bc=json.loads((prior/'checking_vix/score_selected.json').read_text());v=lambda r:r['original_otm_components']['VIX']+r['original_otm_components']['forwards'];add(f"|Selected baseline|{v(base):.6f}|{base['canonical_components']['VIX']+base['canonical_components']['forwards']:.6f}|{v(bc):.6f}|{base['original_otm_components']['SPX']:.6f}|{base['original_otm_loss']:.6f}|")
    for n in ['higher_L','logtail025']:
        name=n+'_fit';r=json.loads((root/'followup'/f'score_{name}.json').read_text());c=json.loads((root/'followup/checking_vix'/f'score_{name}.json').read_text());add(f"|{name}|{v(r):.6f}|{r['canonical_components']['VIX']+r['canonical_components']['forwards']:.6f}|{v(c):.6f}|{r['original_otm_components']['SPX']:.6f}|{r['original_otm_loss']:.6f}|")
    add();add('These are diagnostic VIX-only fits, NOT accepted joint calibrations. Both also worsen the training common-call VIX-plus-forward criterion, despite improving native OTM VIX; the dual-convention safeguard is materially relevant. Both reach the6% floor endpoint and the xi=.2 bound near day118. VIX-only data do not identify curve pieces outside their30-day windows; the weak roughness penalty can move those pieces substantially. The higher-L fit, for example, takes the0–27-day variance from0.04899 to0.00367 and damages short SPX. Consequently these SPX tradeoffs mix cap changes, fitted-window changes and poorly identified off-window curve changes; they do not isolate the cap cost or prove joint-fit guards are overly restrictive. The useful finding is that removing joint guards permits further sampled VIX improvement, while joint information is essential to control the curve. A next VIX-only diagnostic should freeze off-window pieces and floor before interpreting SPX costs.');add()
    for n in ['higher_L','logtail025']:
        r=json.loads((root/'followup'/f'checking_paired_{n}_fit.json').read_text());s=json.loads((root/'followup'/f'paired_{n}.json').read_text());add(f"- {n}_fit: separate-checking native VIX-plus-forward change{r['change'][2]:.6f}, descriptive paired eight-net jackknife SE{r['jackknife_SE'][2]:.6f}. Training SPX loss change{s['change'][1]:.3f}, paired eight-block SE{s['jackknife_SE'][1]:.3f}.")
    add();add('Checking streams were used previously and score the SAME market quotes. They are not untouched holdout or market out-of-sample data. SPX checking on separate streams was not repeated. Signed prices, unavailable IVs, shape flags and raw stock-forward diagnostics remain in saved scores/arrays. In particular baseline training day1030 raw stock-forward ratio is about0.9624 with iid SE0.00927: no new stock sampling clearance follows.');add()
    add('## Stochastic vol-of-vol follow-up');add();add('After cap profiles, two bounded fixed-curve experiments let existing cluster C change the mixture weight between original and stronger-spike responses. Original OU/randomness remain unchanged. Native VIX-plus-forward losses worsen to87.177224 and117.866292 (spike boost.5 and1). These tests also bend the far wing downward at several dates. No cluster candidate was promoted to a joint fit or a full SPX claim. This rejects those profiles as immediate improvements, not every cluster mechanism.');add();add('The linked stochastic-vol-of-vol report explains Ito response strength, the implemented bounded mixture, a dedicated continuous latent OU response state, an alternative latent mixture, identification, boundedness/martingality, randomness and cache reuse. A dedicated state is explicitly proposed rather than implemented. It would require new state simulation, four-dimensional conditional pricing, and full volatility/stock recomputation; one stored float64 state on the current stock cache costs26.05GiB.');add()
    add('## Numerical checks and unresolved issues');add()
    ref=json.loads((root/'refinement.json').read_text());add(f"- New readout/stock kernels match independent Python equations and the adapted stock recursion. Tests were run directly because this environment has no pytest module; the initial pytest-launch failure is retained.")
    add(f"- Same-GH direct conditional probes give maximum interpolation relative errors2.23e-10 for cap profiles and1.85e-8 for cluster profiles; independent randomized tensor checks also pass. These are sampled interpolation checks, not global bounds.")
    add(f"- At representative outer states (first, largest VIX and largest weighted highest-strike payoff), all four maturities and baseline/higherL/logtail025 profiles: conditional GH32→48 maximum VIX change{ref['maximum_conditional_GH_change']:.3g}; time order8→16 maximum{ref['maximum_time_change']:.3g}. Normalizer GH48/64/96 midpoint values are also saved. This does not certify the whole surface or the fitted curves.")
    add('- Baseline separate-checking153-day second moment remains606.20794 versus610.93257 with net SE1.63548. HigherL fixed-curve checking gives605.78268 with SE1.68207 against the SAME target. Raising the cap does not remove that deficit. Direct marginal moment agreement and the small conditional probes point away from those tested integration errors, while outer-tail/proposal errors remain open.')
    add('- Removing the cap is not tested as a solution: selected uncapped first moments are finite, but long-date second multiplier moments are infinite (critical moment power1.11480). Higher curvatures can also destroy first moments. The continuous stock martingale is not certified merely by a finite normalizer. Bounded and controlled-growth alternatives have separate mathematical arguments in the equation report.')
    add('- Independent audit replays every saved price/SE/parity/loss, exact4096 allocation, candidate constraint and captured source snapshot. It does not regenerate original primitives or prove the numerical model equivalent to the continuous SDE. No new Lean or P-compatibility certificate is asserted.');add()
    add('## Decision and continuation');add();add('Preserve the selected baseline. The cap is a real finite-state compression mechanism and an adjustable wing-shape lever, but this bounded study does not establish it as the sole cause or exhibit a satisfactory joint remedy. Logarithmic continuation remains a mathematically controlled experimental family; it is not selected after these tests. Avoid an expensive24-parameter recalibration before a more focused shape design. Next isolate the response-versus-level tradeoff with off-window curve pieces fixed, then compare cluster modulation against a dedicated bounded latent response. Keep jumps and quintic approaches excluded. Do not relax floor/beta constraints or change the existing reservoir.');add()
    add('Plots: [cap location/sharpness](visualizations/cap-tail-014/vix-cap-location.png), [alternative cap shapes](visualizations/cap-tail-014/vix-cap-shapes.png), [weighted tail calls](visualizations/cap-tail-014/weighted-tail-calls.png), [VIX-only fits](visualizations/cap-tail-014/vix-focused-fits.png), [all seven SPX maturities](visualizations/cap-tail-014/spx-all-maturities-iv.png), [separate VIX checking](visualizations/cap-tail-014/vix-separate-checking.png). All have SVG exports; signed-price/error and forward plots are retained.');add()
    add('Reproduction modules: `cap_tail_study`, `cap_tail_diagnostics`, `cap_tail_followup`, `cluster_vov_study`, `cap_tail_refinement`, `audit_cap_tail`, `plot_cap_tail`, `summarize_cap_tail`. Run with `OPENBLAS_NUM_THREADS=1 VECLIB_MAXIMUM_THREADS=1 PYTHONPATH=matteo/exogenous_reservoir_eq_m2/src /private/tmp/pdv-options-venv/bin/python -m matteo.model_comparison.option_pricing.<module>`. Initial driver takes `--output NEW_DIRECTORY`; followup takes `--run`. Auxiliary postprocessors currently name001 explicitly. Do not rerun mutation drivers over existing directories; their mkdir checks protect originals. Full command/config/source/run records are saved.');add()
    import re
    text='\n'.join(lines)+'\n'
    for word in ['dates','all','cutoff','stock','most','are','strikes','roughly','contribute','is','scrambled','tested','forwards','baseline','market','At','At','price is','SEs are','free','The','the','day','windows','from','to','change','SE','point','points','power','costs','expensive','variance','terms','same','below','of','with']:
        text=re.sub(r'\b('+re.escape(word)+r')(?=[0-9])',r'\1 ',text)
    (HERE/'CAP_TAIL_RESULTS.md').write_text(text)
    print('Wrote CAP_TAIL_RESULTS.md')
if __name__=='__main__':run()
